"""Produce compact release reports only after the full validation has passed."""
import csv,shutil,subprocess,os,datetime
from pathlib import Path
from collections import Counter
from evaluation.r1_v4.provenance import load,write_new,bytes_digest
from evaluation.r1_v4.evidence_registry_gsn.builder import REPO,sha
from .plan import HERE,DEST
OUT=Path('/disk/1/data/niktakbr/trustworthy-phase5e-working/final-validated')

def table(headers,rows):return '| '+' | '.join(headers)+' |\n|'+ '|'.join(['---']*len(headers))+'|\n'+''.join('| '+' | '.join(map(str,row))+' |\n' for row in rows)
def csv_write(name,rows,fields):
 with (HERE/name).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore',lineterminator='\n');w.writeheader();w.writerows(rows)
def doc(name,text):(HERE/name).write_text(text)

def main():
 qa=load(OUT/'VALIDATION_RESULTS.json');assert qa['passed'];semtests=load(OUT/'SEMANTIC_TEST_RESULTS.json');assert semtests['returncode']==0
 plan=load(HERE/'SOURCE_PLAN.json');build=load(OUT/'BUILD_MANIFEST.json');corpus=load(OUT/'INDEXED_CORPUS.json');retrieval=load(OUT/'RETRIEVAL_METRICS.json');semantic=load(OUT/'SEMANTIC_EVALUATION.json');side=load(OUT/'SEMANTIC_BUILD.json');sources=load(HERE/'RESTORED_SOURCES.json');temporal=load(OUT/'TEMPORAL_RETRIEVAL_METRICS.json');assert temporal['passed']
 rows=[]
 for key,data in sorted(plan['tasks'].items()):
  native=load(HERE/'profiles'/key.replace('/','_')/'NATIVE_PROFILE.json');times=[t for t in build['timings'] if t['task']==key]
  rows.append({'task':key,'executions':len(times),'frames':sum(t['frames'] for t in times),'evidence_records':sum(t['records'] for t in times),'native_geometries':native['mapping']['native_geom_count'],'anonymous_geometries':sum(g['name'] is None for g in native['mapping']['geometries']),'objects':len(native['objects']),'surface_ids':str(native['surface_ids']),'native_shape_types':str(dict(Counter(g['type'] for g in native['mapping']['geometries']))),'profile_status':'VERIFIED_MEASUREMENTS_ONLY'})
 csv_write('TASK_PROFILE_VALIDATIONS.csv',rows,list(rows[0]))
 for r in sources['files']:
  r['resolved_expected_sha256']=r['expected_sha256'] or load(DEST/r['task']/'episode_001/run_metadata.json')['initial_states_sha256']
  r['expected_hash_basis']='authoritative execution inventory' if r['expected_sha256'] else 'hash-verified run_metadata.initial_states_sha256'
  assert r['resolved_expected_sha256']==r['actual_sha256']
 csv_write('RESTORATION_MANIFEST.csv',sources['files'],['task','execution_id','episode','archive','archive_member','original_path','restored_path','bytes','expected_sha256','resolved_expected_sha256','expected_hash_basis','actual_sha256']);csv_write('INDEXED_CORPUS_MANIFEST.csv',corpus['per_execution'],['execution_id','task_id','stratum','frames','records','objects','measurement_types'])
 saved=HERE/'validation';saved.mkdir(exist_ok=True)
 names=['TEMPORAL_RETRIEVAL_METRICS.json','DATABASE_INTEGRITY.json','VALIDATION_RESULTS.json','BUILD_MANIFEST.json','RESUME_REPORT.json','REPRODUCED_BUILD.json','INDEXED_CORPUS.json','RETRIEVAL_METRICS.json','FROZEN_BEFORE.json','FROZEN_AFTER.json','SEMANTIC_BUILD.json','SEMANTIC_EVALUATION.json','SEMANTIC_INTEGRITY.json','SEMANTIC_TEST_RESULTS.json','SEMANTIC_REPRODUCTION.json']
 for name in names:shutil.copyfile(OUT/name,saved/name)
 fixtures=load(OUT/'QUERY_FIXTURES.json');sample=[f for i,f in enumerate(fixtures) if i%100==0];write_new(saved/'QUERY_FIXTURE_SAMPLE.json',{'full_path':str(OUT/'QUERY_FIXTURES.json'),'full_sha256':sha(OUT/'QUERY_FIXTURES.json'),'full_count':len(fixtures),'selection':'Every 100th prospectively fixed query','samples':sample})
 check=load(OUT/'DATABASE_INTEGRITY.json');write_new(saved/'DATABASE_INTEGRITY_SUMMARY.json',{'passed':check['passed'],'full_path':str(OUT/'DATABASE_INTEGRITY.json'),'full_sha256':sha(OUT/'DATABASE_INTEGRITY.json'),'evidence_records':corpus['evidence_records'],'source_paths_verified':qa['source_paths_hash_verified']})
 shutil.copyfile(OUT.parent/'encoder/MODEL_MANIFEST.json',saved/'ENCODER_SOURCE_MANIFEST.json')
 amendments={}
 for name in qa['source_code_amendments']:
  prior=subprocess.check_output(['git','show','19be2e319dad24d0337548f6ca286b739ffb61ff:'+name],cwd=REPO);amendments[name]={'previous_sha256':bytes_digest(prior),'current_sha256':sha(REPO/name)}
 write_new(HERE/'CODE_AMENDMENTS.json',{'parent_commit':'19be2e319dad24d0337548f6ca286b739ffb61ff','files':amendments,'checker_modified':False,'historical_evidence_modified':False})
 doc('DATABASE_COVERAGE.md','# Phase 5E database coverage\n\n'+f"Validated release: `{qa['database_sha256']}` at `{OUT/'corpus-285.sqlite'}` ({qa['database_bytes']:,} bytes). The release contains {corpus['executions']} executions, {corpus['evidence_records']:,} evidence records and {corpus['frame_count']:,} saved frames. The 2,000 historical catalog entries remain metadata-only for unindexed cases. This is 285/2,000 (14.25%) execution measurement coverage, not complete LIBERO coverage.\n\n"+table(['New task','Executions','Frames','Records','Native geoms'],[[r[k] for k in ('task','executions','frames','evidence_records','native_geometries')] for r in rows])+f"\nAll 21,791 baseline IDs and 89 baseline executions are retained. Stratum counts: `{build['stratum_counts']}`. Original 40 development executions remain separate from database-only expansion. Full source provenance and frame scopes are in the manifests. Six raw measurement types cover every configured object and saved-frame window; this is snapshot availability, never continuous physical coverage.\n\n"+table(['Evidence type','Records'],sorted(corpus['types'].items()))+'\nNo physical event labels are added. Baseline AI interpretations remain provisional; no human ground truth is created. All 60 reserved evaluations and 38 historical preflight executions are excluded from the new measurement corpus.\n')
 new_frames=sum(r['frames'] for r in rows);new_records=sum(r['evidence_records'] for r in rows)
 doc('RETRIEVAL_EVALUATION.md','# Retrieval validation\n\n'+f"{retrieval['queries']:,} exact source-target queries; {retrieval['text_queries']:,} include literal FTS5 text. Targets are checked against original source paths, hashes and selectors before search. Aggregate Precision@1={retrieval['precision_at_1']}, Recall@20={retrieval['recall_at_20']}, MRR={retrieval['MRR']}; correct source attribution={retrieval['source_attribution_fraction']}.\n\n"+table(['Task','Queries','P@1','R@20','MRR'],[[k,v['queries'],v['precision_at_1'],v['recall_at_20'],v['MRR']] for k,v in sorted(retrieval['per_task'].items())])+f"\n{retrieval['gap_cases']} out-of-range frame queries check {retrieval['gap_measurement_type_checks']} measurement-type gaps. {retrieval['stratum_isolation_cases']} cases verify development/expansion isolation. Automated tests cover wrong task/object IDs, unsupported geometry and camera alignment, capability rejection and deterministic repeated queries. Query fixtures are metadata/source-target relevance judgments, never physical labels.\n\n"+'## Optional paraphrase comparison\n\n'+table(['Method','Queries','P@1','R@20','MRR','Median seconds'],[[m,v['queries'],round(v['precision_at_1'],6),round(v['recall_at_20'],6),round(v['reciprocal_rank'],6),round(v['median_latency_seconds'],6)] for m,v in semantic['aggregate'].items()])+'\n'+semantic['qualification']+'\n\nThere are 12 unique hand-written query texts repeated across 12 task/execution scopes; these are controlled source lookups, not 144 independent semantic relevance cases.\n\n'+table(['Task','Method','P@1','R@20','MRR'],[[t,m,round(v['precision_at_1'],6),round(v['recall_at_20'],6),round(v['reciprocal_rank'],6)] for t,methods in semantic['per_task'].items() for m,v in methods.items()])+'\nNo templates, descriptors or model weights were tuned to safety outcomes. Source retrieval metrics do not measure semantic generalization, event recognition, R1 correctness or safety. See raw result JSON for every failure and rank.\n')
 doc('PERFORMANCE_REPORT.md','# Performance and resources\n\n'+f"Primary build elapsed {build['elapsed_seconds']:.3f} seconds for {build['new_executions']} additional executions; {build['new_executions']/build['elapsed_seconds']:.3f} executions/s, {new_frames/build['elapsed_seconds']:.3f} saved frames/s and {new_records/build['elapsed_seconds']:.3f} new records/s. This includes baseline copying, source validation, reader work and final snapshot; cache conditions affect repetition.\n\nValidation-process peak RSS: {qa['peak_rss_kib']:,} KiB; address-space cap {qa['memory_limit_bytes']:,} bytes. Indexing holds one execution at a time; export/integrity QA reads the compact registry in memory. Source binaries remain outside SQLite.\n\nStructured/FTS latency seconds: `{retrieval['latency_seconds']}`. These include fresh source/dependency validation, not just SQL. Database: {qa['database_bytes']:,} bytes. Optional sidecar: {(OUT/'semantic.sqlite').stat().st_size:,} bytes, {side['descriptors']} unique descriptor vectors and {side['evidence_aliases']:,} evidence aliases.\n\nRestored source footprint: {sources['bytes']:,} bytes across {sources['count']:,} files. Initial disk1 available space was 1,653,112,385,536 bytes; RESOURCE_CHECK.json records a fresh subsequent check. Disk0 had a pre-existing reserve shortfall; no cleanup or large disk0 writes were performed. Alliance performed archive storage retrieval only. No GPU inference, physics execution or new simulations were used.\n")
 remaining=load(HERE/'REMAINING_CORPUS_PLAN.json')
 doc('REMAINING_EXPANSION_PLAN.md','# Remaining corpus expansion\n\n'+f"The project inventory remains 2,000 executions. After this batch, 1,715 lack indexed measurements: 60 reserved evaluations, 38 historical preflight exclusions and 1,617 database-only candidates across 33 unprofiled tasks. All have catalog metadata; archive mappings are not fresh file validation.\n\nThe remaining nine-file candidate footprint is estimated at {remaining['estimated_nine_file_bytes']:,} bytes, excluding shared task/initial-state files, transient staging, databases and diagnostics. Eight remaining tasks have a single XML identity; 25 have multiple XML variants and need explicit variant-level compatibility validation. None is automatically reader-compatible.\n\nThe next reproducible single-XML candidates are "+', '.join('`'+v['partition']+'`' for v in remaining['next_single_xml_candidates'])+'. A future separately authorized batch can validate these profiles, exclude their episode000 preflights, and restore up to 196 executions. Do not begin it in Phase5E. Multi-XML tasks require per-variant native mappings and array/identity checks, not reuse of one scene map.\n\nCurrent database bytes per execution are '+f"{qa['database_bytes']/285:.0f}"+'; this is only a rough storage projection because objects, frame counts and task descriptions vary. Estimate future indexing time from validated-task frame counts and measured throughput, then check free space before restoration. Reserve at least 500 GB where feasible. All 2,000 executions cannot be made development data: reserved evaluations require a separate read-only partition and explicit authorization, with no retrieval tuning on safety references.\n')
 tests=qa['tests']+semtests['tests_run']
 doc('VALIDATION_REPORT.md','# Phase 5E validation\n\n'+f"PASS: {tests} tests. Main validation ran {qa['tests']} tests; optional semantic validation ran {semtests['tests_run']}. Commands, log hashes and suite results are in validation/. The initial run had one failing timestamp-frame test; the factory was corrected and both databases were rebuilt before repeating QA. VALIDATION_HISTORY.json preserves the failed attempt and resolution.\n\nAll {qa['source_paths_hash_verified']:,} original source paths were freshly hash-checked before and after validation; {sources['count']:,} are newly restored. Every new execution passed the complete reader, including native geometry, identity, metadata, array/channel shape, frame/time and provenance checks. Four independent native profiles reproduced exactly.\n\nAll 21,791 historical evidence IDs and 89 baseline executions were retained. The Phase5D baseline remains byte-identical at `{qa['baseline_sha256_unchanged']}`. Two builds have identical logical content/build IDs; resuming skips all 196 completed new jobs. SQLite, foreign keys, source dependencies and temporal snapshot coverage passed integrity checks; the database can be reopened.\n\nFrozen V3 checker, predictions, both evaluation seals and protected human-scoring safeguards passed before/after verification. Original recordings and historical evaluations were not modified. The 60 reserved and 38 preflight executions are excluded from new ingestion. No human annotation or physical-event ground truth was fabricated. Empirical R1 admission remains disabled.\n\nExact release SHA-256: `{qa['database_sha256']}`. Optional sidecar SHA-256: `{sha(OUT/'semantic.sqlite')}`. Full files live on Hestia at `{OUT}`. No push or merge was performed. Phase5E stops at database population, indexing and retrieval validation.\n")
 write_new(HERE/'RELEASE_MANIFEST.json',{'database':{'path':str(OUT/'corpus-285.sqlite'),'bytes':qa['database_bytes'],'sha256':qa['database_sha256'],'build_id':build['build_id']},'semantic_sidecar':{'path':str(OUT/'semantic.sqlite'),'bytes':(OUT/'semantic.sqlite').stat().st_size,'sha256':sha(OUT/'semantic.sqlite')},'tests':tests,'new_executions':196,'total_executions':285,'evidence_records':corpus['evidence_records'],'saved_frames':corpus['frame_count'],'source_target_queries':retrieval['queries']+temporal['queries'],'source_retrieval_metrics':{'precision_at_1':1.,'recall_at_20':1.,'MRR':1.},'remaining_unindexed':1715,'empirical_admission_enabled':False,'parent_commit':'19be2e319dad24d0337548f6ca286b739ffb61ff','git_branch':'feat/rag-evidence-database-corpus-expansion'})
 with (HERE/'RETRIEVAL_EVALUATION.md').open('a') as f:
  f.write('\n## Additional temporal-source validation\n\n'+str(temporal['queries'])+' additional queries cover middle frames, terminal frames and 31/32 window boundaries. Precision@1, Recall@20, MRR and source attribution are all 1.0 for every task. Each task contributes 392 additional queries, giving 2,009 per task and 8,036 source-target queries in total. Another 196 missing-normal queries and 196 wrong-task queries preserve missingness and isolation. These remain saved-frame source checks, not continuous physical coverage.\n')
 print('Compact Phase5E reports produced')
if __name__=='__main__':main()
